            has_prerelease = True
            prerelease_identifiers = prerelease_part.split('.')
        else:
            version_part = v_without_build
            has_prerelease = False
            prerelease_identifiers = []

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, has_prerelease, prerelease_identifiers)

