        # Compare pre-release identifiers
        for i in range(max(len(identifiers1), len(identifiers2))):
            if i >= len(identifiers1):
                # identifiers1 is shorter, so it comes first
                return -1
            if i >= len(identifiers2):
                # identifiers2 is shorter, so it comes first
                return 1

            id1 = identifiers1[i]
            id2 = identifiers2[i]

            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both are numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                elif num1 > num2:
                    return 1
            elif is_digit1:
                # Only id1 is numeric, numeric comes first
                return -1
            elif is_digit2:
                # Only id2 is numeric, numeric comes first
                return 1
            else:
                # Both are non-numeric, compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        return 0

    def compare_versions(parsed1, parsed2):
        major1, minor1, patch1, has_pre1, pre_ids1 = parsed1
        major2, minor2, patch2, has_pre2, pre_ids2 = parsed2

        # Compare MAJOR.MINOR.PATCH
        if major1 != major2:
            return -1 if major1 < major2 else 1
        if minor1 != minor2:
            return -1 if minor1 < minor2 else 1
        if patch1 != patch2:
            return -1 if patch1 < patch2 else 1

        # Same MAJOR.MINOR.PATCH
        if has_pre1 and not has_pre2:
            # has_pre1 sorts before no pre-release
            return -1
        elif not has_pre1 and has_pre2:
            # no pre-release sorts after pre-release
            return 1
