    parsed_with_index = [(parse_version(v), i, v) for i, v in enumerate(versions)]

    # Sort using stable sort (preserves original order for equal precedence)
    parsed_with_index.sort(key=lambda x: (x[0][:4], x[1]))

    # Return sorted version strings
    return [v for _, _, v in parsed_with_index]

